import hashlib, os

def hash_tree(root: str) -> str:
    h = hashlib.sha256()
    for dirpath, _, filenames in os.walk(root):
        for fn in filenames:
            full = os.path.join(dirpath, fn)
            rel = os.path.relpath(full, root)
            h.update(rel.encode('utf-8'))
            with open(full, 'rb') as f:
                h.update(f.read())
    return h.hexdigest()

