Because touching half-open intervals `[a, b)` and `[b, c)` form the contiguous union `[a, c)`, the merge condition after sorting is `start <= prev_end`:

```python
from typing import List, Sequence, Tuple


def merge_intervals(intervals: Sequence[Tuple[int, int]]) -> List[Tuple[int, int]]:
    for start, end in intervals:
        if start >= end:
            raise ValueError(f"half-open interval must satisfy start < end, got ({start}, {end})")
    if not intervals:
        return []
    ordered = sorted(intervals)
    merged: List[Tuple[int, int]] = [ordered[0]]
    for start, end in ordered[1:]:
        prev_start, prev_end = merged[-1]
        if start <= prev_end:
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))
    return merged
```

